-- SQL Server 2019+。先选择 XuriTraining 数据库，再一次性执行本文件。
SET XACT_ABORT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_PADDING ON;
SET ANSI_WARNINGS ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET ARITHABORT ON;
SET NUMERIC_ROUNDABORT OFF;
BEGIN TRANSACTION;
CREATE TABLE department(id bigint IDENTITY PRIMARY KEY,name nvarchar(100) NOT NULL,parent_id bigint NULL REFERENCES department(id));
CREATE TABLE job_position(id bigint IDENTITY PRIMARY KEY,name nvarchar(100) NOT NULL);
CREATE TABLE job_grade(id bigint IDENTITY PRIMARY KEY,name nvarchar(100) NOT NULL,sort_order int NOT NULL DEFAULT 0);
CREATE TABLE app_user(id bigint IDENTITY PRIMARY KEY,username nvarchar(80) NOT NULL UNIQUE,password_hash varchar(100) NOT NULL,display_name nvarchar(100) NOT NULL,department_id bigint NULL REFERENCES department(id),position_id bigint NULL REFERENCES job_position(id),grade_id bigint NULL REFERENCES job_grade(id),active bit NOT NULL DEFAULT 1,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE user_role(user_id bigint NOT NULL REFERENCES app_user(id),role varchar(20) NOT NULL CHECK(role IN('EMPLOYEE','INSTRUCTOR','MANAGER','ADMIN')),PRIMARY KEY(user_id,role));
CREATE TABLE manager_department(user_id bigint NOT NULL REFERENCES app_user(id),department_id bigint NOT NULL REFERENCES department(id),PRIMARY KEY(user_id,department_id));
CREATE TABLE auth_token(token_hash char(64) PRIMARY KEY,user_id bigint NOT NULL REFERENCES app_user(id),expires_at datetime2 NOT NULL);
CREATE INDEX ix_token_user ON auth_token(user_id);
CREATE TABLE login_guard(username nvarchar(80) PRIMARY KEY,failures int NOT NULL,blocked_until datetime2 NULL);
CREATE TABLE file_asset(id uniqueidentifier PRIMARY KEY,owner_id bigint NOT NULL REFERENCES app_user(id),name nvarchar(200) NOT NULL,storage_name varchar(50) NOT NULL,content_type varchar(100) NOT NULL,size_bytes bigint NOT NULL,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE media_ticket(token_hash char(64) PRIMARY KEY,asset_id uniqueidentifier NOT NULL REFERENCES file_asset(id),user_id bigint NOT NULL REFERENCES app_user(id),expires_at datetime2 NOT NULL);
CREATE TABLE course(id bigint IDENTITY PRIMARY KEY,owner_id bigint NOT NULL REFERENCES app_user(id),title nvarchar(200) NOT NULL,description nvarchar(3000) NOT NULL,category nvarchar(100) NOT NULL,status varchar(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','PENDING','PUBLISHED','REJECTED','ARCHIVED')),version int NOT NULL DEFAULT 1,review_note nvarchar(1000) NULL,reviewer_id bigint NULL REFERENCES app_user(id),created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE lesson(id bigint IDENTITY PRIMARY KEY,course_id bigint NOT NULL REFERENCES course(id),title nvarchar(200) NOT NULL,sort_order int NOT NULL,duration_seconds int NOT NULL CHECK(duration_seconds>0),video_asset_id uniqueidentifier NULL REFERENCES file_asset(id),coverage_threshold decimal(5,4) NOT NULL DEFAULT .95 CHECK(coverage_threshold BETWEEN .5 AND 1),time_threshold decimal(5,4) NOT NULL DEFAULT .95 CHECK(time_threshold BETWEEN .5 AND 1),UNIQUE(course_id,sort_order));
CREATE TABLE course_material(id bigint IDENTITY PRIMARY KEY,course_id bigint NOT NULL REFERENCES course(id),title nvarchar(200) NOT NULL,content nvarchar(max) NOT NULL,asset_id uniqueidentifier NULL REFERENCES file_asset(id));
CREATE TABLE course_review(id bigint IDENTITY PRIMARY KEY,course_id bigint NOT NULL REFERENCES course(id),actor_id bigint NOT NULL REFERENCES app_user(id),action varchar(30) NOT NULL,note nvarchar(1000) NOT NULL,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE course_enrollment(user_id bigint NOT NULL REFERENCES app_user(id),course_id bigint NOT NULL REFERENCES course(id),completed bit NOT NULL DEFAULT 0,enrolled_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),completed_at datetime2 NULL,PRIMARY KEY(user_id,course_id));
CREATE TABLE learning_path(id bigint IDENTITY PRIMARY KEY,title nvarchar(200) NOT NULL,position_id bigint NULL REFERENCES job_position(id),grade_id bigint NULL REFERENCES job_grade(id),version int NOT NULL DEFAULT 1,published bit NOT NULL DEFAULT 0);
CREATE TABLE path_stage(id bigint IDENTITY PRIMARY KEY,path_id bigint NOT NULL REFERENCES learning_path(id),title nvarchar(200) NOT NULL,sort_order int NOT NULL,UNIQUE(path_id,sort_order));
CREATE TABLE stage_course(stage_id bigint NOT NULL REFERENCES path_stage(id),course_id bigint NOT NULL REFERENCES course(id),PRIMARY KEY(stage_id,course_id));
CREATE TABLE path_assignment(user_id bigint NOT NULL REFERENCES app_user(id),path_id bigint NOT NULL REFERENCES learning_path(id),assigned_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),PRIMARY KEY(user_id,path_id));
CREATE TABLE training_plan(id bigint IDENTITY PRIMARY KEY,title nvarchar(200) NOT NULL,start_at datetime2 NOT NULL,due_at datetime2 NOT NULL,owner_id bigint NOT NULL REFERENCES app_user(id),status varchar(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','PUBLISHED','CLOSED')),CHECK(due_at>start_at));
CREATE TABLE plan_course(plan_id bigint NOT NULL REFERENCES training_plan(id),course_id bigint NOT NULL REFERENCES course(id),PRIMARY KEY(plan_id,course_id));
CREATE TABLE plan_member(plan_id bigint NOT NULL REFERENCES training_plan(id),user_id bigint NOT NULL REFERENCES app_user(id),PRIMARY KEY(plan_id,user_id));
CREATE TABLE learning_session(id uniqueidentifier PRIMARY KEY,user_id bigint NOT NULL REFERENCES app_user(id),lesson_id bigint NOT NULL REFERENCES lesson(id),active bit NOT NULL,last_seq int NOT NULL DEFAULT 0,last_position float NOT NULL DEFAULT 0,last_at_ms bigint NOT NULL,playing bit NOT NULL DEFAULT 0,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE UNIQUE INDEX ux_one_active_session ON learning_session(user_id) WHERE active=1;
CREATE TABLE learning_event(id bigint IDENTITY PRIMARY KEY,session_id uniqueidentifier NOT NULL REFERENCES learning_session(id),seq int NOT NULL,event_type varchar(30) NOT NULL,position_seconds float NOT NULL,accepted_seconds float NOT NULL,reason nvarchar(200) NOT NULL,received_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),UNIQUE(session_id,seq));
CREATE TABLE watch_segment(id bigint IDENTITY PRIMARY KEY,user_id bigint NOT NULL REFERENCES app_user(id),lesson_id bigint NOT NULL REFERENCES lesson(id),session_id uniqueidentifier NOT NULL REFERENCES learning_session(id),start_seconds float NOT NULL,end_seconds float NOT NULL,valid bit NOT NULL DEFAULT 1,CHECK(end_seconds>=start_seconds));
CREATE INDEX ix_watch_user_lesson ON watch_segment(user_id,lesson_id);
CREATE TABLE watch_progress(user_id bigint NOT NULL REFERENCES app_user(id),lesson_id bigint NOT NULL REFERENCES lesson(id),effective_seconds float NOT NULL DEFAULT 0,covered_seconds float NOT NULL DEFAULT 0,completed bit NOT NULL DEFAULT 0,PRIMARY KEY(user_id,lesson_id));
CREATE TABLE warning(id bigint IDENTITY PRIMARY KEY,user_id bigint NOT NULL REFERENCES app_user(id),course_id bigint NULL REFERENCES course(id),session_id uniqueidentifier NULL REFERENCES learning_session(id),type varchar(30) NOT NULL,severity varchar(10) NOT NULL,status varchar(20) NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','INVESTIGATING','REVIEW','CLOSED')),evidence nvarchar(max) NOT NULL,occurrences int NOT NULL DEFAULT 1,handler_id bigint NULL REFERENCES app_user(id),created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),updated_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE warning_action(id bigint IDENTITY PRIMARY KEY,warning_id bigint NOT NULL REFERENCES warning(id),actor_id bigint NOT NULL REFERENCES app_user(id),action varchar(30) NOT NULL,note nvarchar(2000) NOT NULL,before_state varchar(20) NOT NULL,after_state varchar(20) NOT NULL,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE question(id bigint IDENTITY PRIMARY KEY,course_id bigint NOT NULL REFERENCES course(id),owner_id bigint NOT NULL REFERENCES app_user(id),type varchar(20) NOT NULL CHECK(type IN('SINGLE','MULTIPLE','TRUE_FALSE','TEXT')),stem nvarchar(4000) NOT NULL,options_json nvarchar(max) NOT NULL,answer nvarchar(2000) NOT NULL,explanation nvarchar(4000) NOT NULL,source varchar(20) NOT NULL DEFAULT 'MANUAL',status varchar(20) NOT NULL DEFAULT 'APPROVED' CHECK(status IN('DRAFT','APPROVED')),created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE paper(id bigint IDENTITY PRIMARY KEY,title nvarchar(200) NOT NULL,owner_id bigint NOT NULL REFERENCES app_user(id),published bit NOT NULL DEFAULT 0,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE paper_question(id bigint IDENTITY PRIMARY KEY,paper_id bigint NOT NULL REFERENCES paper(id),question_id bigint NOT NULL REFERENCES question(id),sort_order int NOT NULL,score int NOT NULL CHECK(score>0),snapshot_json nvarchar(max) NOT NULL,UNIQUE(paper_id,question_id),UNIQUE(paper_id,sort_order));
CREATE TABLE exam(id bigint IDENTITY PRIMARY KEY,title nvarchar(200) NOT NULL,paper_id bigint NOT NULL REFERENCES paper(id),owner_id bigint NOT NULL REFERENCES app_user(id),stage_id bigint NULL REFERENCES path_stage(id),start_at datetime2 NOT NULL,end_at datetime2 NOT NULL,duration_minutes int NOT NULL CHECK(duration_minutes>0),pass_score int NOT NULL CHECK(pass_score>0),max_attempts int NOT NULL DEFAULT 2 CHECK(max_attempts BETWEEN 1 AND 10),CHECK(end_at>start_at));
CREATE TABLE exam_prerequisite(exam_id bigint NOT NULL REFERENCES exam(id),course_id bigint NOT NULL REFERENCES course(id),PRIMARY KEY(exam_id,course_id));
CREATE TABLE exam_member(exam_id bigint NOT NULL REFERENCES exam(id),user_id bigint NOT NULL REFERENCES app_user(id),PRIMARY KEY(exam_id,user_id));
CREATE TABLE plan_exam(plan_id bigint NOT NULL REFERENCES training_plan(id),exam_id bigint NOT NULL REFERENCES exam(id),PRIMARY KEY(plan_id,exam_id));
CREATE TABLE exam_attempt(id uniqueidentifier PRIMARY KEY,exam_id bigint NOT NULL REFERENCES exam(id),user_id bigint NOT NULL REFERENCES app_user(id),attempt_no int NOT NULL,status varchar(20) NOT NULL DEFAULT 'IN_PROGRESS' CHECK(status IN('IN_PROGRESS','PENDING_GRADE','GRADED')),started_at_ms bigint NOT NULL,deadline_ms bigint NOT NULL,score int NULL,passed bit NOT NULL DEFAULT 0,submitted_at_ms bigint NULL,UNIQUE(exam_id,user_id,attempt_no));
CREATE UNIQUE INDEX ux_one_exam ON exam_attempt(user_id,exam_id) WHERE status='IN_PROGRESS';
CREATE TABLE exam_answer(attempt_id uniqueidentifier NOT NULL REFERENCES exam_attempt(id),paper_question_id bigint NOT NULL REFERENCES paper_question(id),answer nvarchar(4000) NOT NULL,score int NULL,grader_id bigint NULL REFERENCES app_user(id),PRIMARY KEY(attempt_id,paper_question_id));
CREATE TABLE exam_event(id bigint IDENTITY PRIMARY KEY,attempt_id uniqueidentifier NOT NULL REFERENCES exam_attempt(id),event_type varchar(20) NOT NULL,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE notification(id bigint IDENTITY PRIMARY KEY,user_id bigint NOT NULL REFERENCES app_user(id),title nvarchar(200) NOT NULL,body nvarchar(2000) NOT NULL,read_at datetime2 NULL,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE INDEX ix_notification_user ON notification(user_id,created_at);
CREATE TABLE assignment(id bigint IDENTITY PRIMARY KEY,course_id bigint NOT NULL REFERENCES course(id),title nvarchar(200) NOT NULL,instructions nvarchar(3000) NOT NULL);
CREATE TABLE assignment_submission(id bigint IDENTITY PRIMARY KEY,assignment_id bigint NOT NULL REFERENCES assignment(id),user_id bigint NOT NULL REFERENCES app_user(id),content nvarchar(4000) NOT NULL,asset_id uniqueidentifier NULL REFERENCES file_asset(id),score int NULL CHECK(score BETWEEN 0 AND 100),feedback nvarchar(2000) NULL,grader_id bigint NULL REFERENCES app_user(id),UNIQUE(assignment_id,user_id));
CREATE TABLE course_feedback(user_id bigint NOT NULL REFERENCES app_user(id),course_id bigint NOT NULL REFERENCES course(id),rating int NOT NULL CHECK(rating BETWEEN 1 AND 5),comment nvarchar(2000) NOT NULL,PRIMARY KEY(user_id,course_id));
CREATE TABLE certificate(id uniqueidentifier PRIMARY KEY,user_id bigint NOT NULL REFERENCES app_user(id),path_id bigint NOT NULL REFERENCES learning_path(id),status varchar(20) NOT NULL DEFAULT 'VALID' CHECK(status IN('VALID','REVOKED')),issued_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),UNIQUE(user_id,path_id));
CREATE TABLE ai_request(id bigint IDENTITY PRIMARY KEY,user_id bigint NOT NULL REFERENCES app_user(id),course_id bigint NOT NULL REFERENCES course(id),purpose varchar(20) NOT NULL,status varchar(20) NOT NULL,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE INDEX ix_ai_user_time ON ai_request(user_id,created_at);
CREATE TABLE audit_log(id bigint IDENTITY PRIMARY KEY,actor_id bigint NULL REFERENCES app_user(id),action varchar(60) NOT NULL,target nvarchar(200) NOT NULL,detail nvarchar(2000) NOT NULL,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
COMMIT;
